UPDATE t_command_idempotency
SET lock_owner = #{newLockOwner},
lock_until = #{newLockUntil,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler},
version = version + 1,
update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE command_idempotency_id = #{commandIdempotencyId}
AND process_status = 'PROCESSING'
AND recovery_stage = #{expectedStage}
AND version = #{expectedVersion}
AND lock_owner IS NOT NULL
AND lock_until IS NOT NULL
AND (lock_owner = #{newLockOwner}
OR lock_until <= #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler})
AND #{newLockUntil,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
> #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}

UPDATE t_command_idempotency
SET recovery_stage = #{nextStage},
lock_until = #{newLockUntil,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler},
version = version + 1,
update_time = #{updatedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE command_idempotency_id = #{commandIdempotencyId}
AND operation_type = #{operationType}
AND process_status = 'PROCESSING'
AND recovery_stage = #{expectedStage}
AND version = #{expectedVersion}
AND lock_owner = #{lockOwner}
AND lock_until IS NOT NULL
AND lock_until > #{updatedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
AND #{newLockUntil,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
> #{updatedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}

UPDATE t_command_idempotency
SET recovery_stage = #{completedStage},
process_status = #{completedStatus},
response_code = #{responseCode},
response_http_status = #{responseHttpStatus},
response_snapshot_schema_version = #{responseSnapshotSchemaVersion,jdbcType=INTEGER},
response_location = #{responseLocation,jdbcType=VARCHAR},
response_body_json = #{responseBodyJson,jdbcType=LONGVARCHAR},
lock_owner = NULL,
lock_until = NULL,
version = version + 1,
update_time = #{completedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE command_idempotency_id = #{commandIdempotencyId}
AND operation_type = #{operationType}
AND process_status = 'PROCESSING'
AND recovery_stage = #{expectedStage}
AND version = #{expectedVersion}
AND lock_owner = #{lockOwner}
AND lock_until IS NOT NULL
AND lock_until > #{completedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
